// Entry shape: [] labels (fetched) | null (fetch failed → PR-side labels
// only, tier degrades toward medium — never wedges the queue on I/O).
var PRIORITY_ISSUE_LABEL_TTL_MS = 60 * 1000;
var _priorityIssueLabelCache = { entries: {} };

