            localAction: 'validate_pr', deferRedHead: true, limit: 1, id: 'validate-armed' }
    };

    function vfConfig(owner, repo) {
        return { fileMap: { '../.dmtools/config.js':
            'module.exports = { repository: { owner: "' + owner + '", repo: "' + repo + '" } };' } };
    }
    function vfItem(n, extra) {
