    var prMachineAuthorU = machineAuthorModule.resolveMachineAuthor(RUN_JOB_PARAMS, effectiveConfig);
    var isMachinePrU = machineAuthorModule.isMachineAuthored(
        ticket, prMachineAuthorU, effectiveRepoInfo.owner);
