                pr: { number: 1565, head: { sha: HEAD, ref: 'ai/gh-1565' } },
                prComments: STALE_PARK_COMMENT
            },
            onCliExecute: outageCli(JSON.stringify({ workflow_runs: [RED_RUN] }))
