            },
            onCliExecute: vfCli({
                actors: { bb445566cc: { login: 'guest-human', date: '2026-10-07T20:06:13Z',
                                         committer: 'Guest Human', sha: 'bb445566cc', parents: [] } },
                parkedAt: '2026-10-07T20:02:05Z'
            })
        }));
        sm.action({ jobParams: { owner: 'a', repo: 'b', machineAuthor: 'ai-teammate',
