        './validateInputJql.js': loadModule('js/common/validateInputJql.js', makeRequire({ './ticketKeyShapes.js': shapes, './trackers.js': trackers }), {}),
        './trackers.js': trackers
    };
}

function makeSmAgent(opts) {
    opts = opts || {};

    var capturedTriggers = [];
    var capturedLabels = [];
    var capturedStatusMoves = [];
    var capturedJqls = [];
    var capturedCliCommands = [];
    var capturedCloses = [];
    var capturedPrMerges = [];
    var capturedPrLabelAdds = [];
    var capturedPrLabelRemoves = [];
    var capturedPrComments = [];
    var capturedEnvSets = [];
    var capturedScmConfigs = [];
    var capturedIoCacheDrops = [];
    var capturedLogs = [];

