    var raw = file_read({ path: 'sm_github.json' });
    var cfg = typeof raw === 'string' ? JSON.parse(raw) : raw;
    var rules = (cfg.params && cfg.params.jobParams && cfg.params.jobParams.rules) || cfg.rules || [];
